421	// Canonical truthy/falsy/bool parsing for user-supplied configuration
422	// (environment variables, headers, config values). The single implementation
423	// lives in the zero-dependency `dynamo-truthy` crate so that crates which
424	// cannot depend on `dynamo-runtime` share it too; this re-export is the
425	// canonical import path for everything that can.
426	pub use dynamo_truthy::{
427	    env_is_falsey, env_is_truthy, is_falsey, is_truthy, parse_bool, parse_bool_opt,
428	};
429	
430	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
431	pub enum ConsoleLogFormat {
432	    Readable,
433	    Jsonl,
434	}
435	
436	impl ConsoleLogFormat {
437	    fn from_env_value(value: &str) -> Option<Self> {
438	        match value.to_ascii_lowercase().as_str() {
439	            "readable" => Some(Self::Readable),
440	            "jsonl" => Some(Self::Jsonl),
441	            _ => None,
442	        }
443	    }
444	
445	    pub fn as_str(self) -> &'static str {
446	        match self {
447	            Self::Readable => "readable",
448	            Self::Jsonl => "jsonl",
449	        }
450	    }
451	}
452	
453	/// Return whether the legacy `DYN_LOGGING_JSONL` switch is enabled.
454	///
455	/// This remains a separate compatibility signal because older deployments
456	/// also use it to enable local trace-context propagation.
457	pub(crate) fn legacy_jsonl_logging_enabled() -> bool {
458	    env_is_truthy(environment_names::logging::DYN_LOGGING_JSONL)
459	}
460	
461	/// Return the console log format.
462	///
463	/// `DYN_LOGGING_CONSOLE_FORMAT` takes precedence. `DYN_LOGGING_JSONL` remains
464	/// supported as a legacy fallback when the new setting is unset or blank.
465	pub fn console_log_format() -> ConsoleLogFormat {
466	    let legacy_format = || {
467	        if legacy_jsonl_logging_enabled() {
468	            ConsoleLogFormat::Jsonl
469	        } else {
470	            ConsoleLogFormat::Readable
471	        }
472	    };
473	
474	    match std::env::var(environment_names::logging::DYN_LOGGING_CONSOLE_FORMAT) {
475	        Ok(value) if value.trim().is_empty() => legacy_format(),
476	        Ok(value) => match ConsoleLogFormat::from_env_value(value.trim()) {
477	            Some(format) => format,
478	            None => {
479	                eprintln!(
480	                    "Invalid {} value '{}'; using readable console logs",
481	                    environment_names::logging::DYN_LOGGING_CONSOLE_FORMAT,
482	                    value
483	                );
484	                ConsoleLogFormat::Readable
485	            }
486	        },
487	        Err(_) => legacy_format(),
488	    }
489	}
490	
491	/// Return whether the effective console log format is JSONL.
492	pub fn jsonl_logging_enabled() -> bool {
493	    console_log_format() == ConsoleLogFormat::Jsonl
494	}
495	
496	/// Check whether logging with ANSI terminal escape codes and colors is disabled.
497	/// Set the `DYN_SDK_DISABLE_ANSI_LOGGING` environment variable a [`is_truthy`] value
498	pub fn disable_ansi_logging() -> bool {
499	    env_is_truthy(environment_names::logging::DYN_SDK_DISABLE_ANSI_LOGGING)
500	}
501	
502	/// Check whether to use local timezone for logging timestamps (default is UTC)
503	/// Set the `DYN_LOG_USE_LOCAL_TZ` environment variable to a [`is_truthy`] value
504	pub fn use_local_timezone() -> bool {
505	    env_is_truthy(environment_names::logging::DYN_LOG_USE_LOCAL_TZ)
506	}
507	
508	/// Returns true if `DYN_LOGGING_SPAN_EVENTS` is set to a truthy value.
509	pub fn span_events_enabled() -> bool {
510	    env_is_truthy(environment_names::logging::DYN_LOGGING_SPAN_EVENTS)
511	}
