513	#[cfg(test)]
514	mod tests {
515	    use super::*;
516	
517	    #[test]
518	    fn test_runtime_config_builder_overrides_related_fields() -> Result<()> {
519	        let config = RuntimeConfig::builder()
520	            .num_worker_threads(Some(24))
